def noncrossing_handshake_count(numPeople):
    mod=10**9+7;pairs=numPeople//2;dp=[0]*(pairs+1);dp[0]=1
    for size in range(1,pairs+1):
        for left in range(size):dp[size]=(dp[size]+dp[left]*dp[size-1-left])%mod
    return dp[pairs]

